// Records json_parse.json: [input, expected] rows, where expected is
// {"ok": JSON.stringify(JSON.parse(input), null, 2)} or {"err": true} when JSON.parse throws.
// Run: node json_parse.mjs > json_parse.json
const inputs = [
  '{}',
  '[]',
  ' \t\r\n{"a":1}\n',
  '"\\ud83d"',
  '"\\ude00"',
  '"a\\ud83d"',
  '"\\ud83d\\ud83d"',
  '"\\ude00\\ud83d"',
  '"\\ud83d\\ude00"',
  '"\\ud83dx"',
  // The stand-in range of a port that maps lone surrogates into the private use area, and the
  // escape character of the port's scheme: all of them must round-trip byte for byte.
  '"\u{f0000}"',
  '"\u{f0000}\u{f0000}"',
  '"\u{f07ff}\u{f0800}\u{effff}"',
  '"\\udb80\\udc00"',
  '"\\udb80\\udc00d800"',
  '"\u{f0000}d800"',
  '"\u{f0000}\\ud800"',
  '"\\ud800\u{f0000}"',
  '"\\ud800\\ud800"',
  '"\u{f0000}\u{f0000}d800\\ud800"',
  '{"\\ud800":1,"\\udb80\\udc00":2,"\u{f0000}":3,"\u{f0000}d800":4}',
  '{"\\ud800":1,"\\ud800":2}',
  '["\\udfff","\\udb80\\udc00","\u{f0001}"]',
  '{"k\\ud800":"v\\udfff"}',
  '["\\uD83D", "\\uDE00"]',
  '"\\u0000\\u001f\\u007f\\u2028"',
  '"\\/\\b\\f\\n\\r\\t\\"\\\\"',
  '1e400',
  '-1e400',
  '[1e400,-1e400,1e-400]',
  '{"n":1e999}',
  '12345678901234567890',
  '9007199254740993',
  '-9007199254740993',
  '0.1',
  '1E2',
  '1e+2',
  '1.5e-7',
  '-0',
  '[-0,0,-0.0]',
  '123456789012345678901234567890',
  '0.30000000000000004',
  '5e-324',
  '1.7976931348623157e308',
  '{"a":1,"a":2}',
  '{"a":1,"b":2,"a":3}',
  '{"b":1,"10":2,"a":3,"2":4}',
  '{"__proto__":1}',
  '[1,[2,[3,[4]]]]',
  'true',
  'null',
  '  false  ',
  '',
  ' ',
  '{',
  '[1,]',
  '{"a":1,}',
  '{a:1}',
  "{'a':1}",
  '01',
  '+1',
  '1.',
  '.5',
  '1e',
  '0x10',
  'NaN',
  'Infinity',
  'undefined',
  '"\u0001"',
  '"a\nb"',
  '"\\x41"',
  '"\\u12"',
  '"unterminated',
  '[1 2]',
  '{"a" 1}',
  '{"a":1 "b":2}',
  '1 2',
  '\u00a0{}',
  '\ufeff{}',
  '{"a":1}\u0000',
  '"\u2028\u2029"',
  '"\ud83d\ude00"',
];
const rows = inputs.map((input) => {
  try {
    return [input, { ok: JSON.stringify(JSON.parse(input), null, 2) }];
  } catch {
    return [input, { err: true }];
  }
});
// Depth is unbounded in V8 (iterative parser): 100000 levels parse.
const deep = '['.repeat(100000) + ']'.repeat(100000);
JSON.parse(deep);
console.log(JSON.stringify(rows, null, 1));
